import{_ as t,o as e,c as s,a3 as n}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"质量与生产组装配方与能力自检","description":"把测试评测、安全、观测与部署收成可上线配方 A–E，给出 LangSmith / 门禁 / 灰度决策表与跨组自检清单。","frontmatter":{"title":"质量与生产组装配方与能力自检","description":"把测试评测、安全、观测与部署收成可上线配方 A–E，给出 LangSmith / 门禁 / 灰度决策表与跨组自检清单。","outline":[2,3],"article":{"type":"index","structure":"index"}},"headers":[],"relativePath":"ts-ai/quality/assembly/assembly-recipes-checklist.md","filePath":"ts-ai/quality/assembly/assembly-recipes-checklist.md","lastUpdated":1786113687000}'),i={name:"ts-ai/quality/assembly/assembly-recipes-checklist.md"};function r(l,a,p,d,o,c){return e(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="质量与生产组装配方与能力自检" tabindex="-1">质量与生产组装配方与能力自检 <a class="header-anchor" href="#质量与生产组装配方与能力自检" aria-label="Permalink to &quot;质量与生产组装配方与能力自检&quot;">​</a></h1><blockquote><p>作者：cursor-grok-4.5</p></blockquote><p>测试、安全、观测、部署各组偏专题。本篇不重抄 Mock / Gate / Guard 签名，只回答：<strong>要组装成哪种「能上线」结果、抄哪条配方、进 architecture 或对外发布前还缺什么。</strong></p><p>服务端见 <a href="/ts-ai/backend/assembly/assembly-recipes-checklist">AI 服务组装配方</a>；前端见 <a href="/ts-ai/integration/assembly/assembly-recipes-checklist">全栈集成组装配方</a>；知识侧见 <a href="/ts-ai/knowledge/assembly/assembly-recipes-checklist">RAG 与记忆组装配方</a>。本篇站在 <strong>质量与生产横切</strong> 视角。</p><h2 id="_1-你要组装的结果形态" tabindex="-1">1. 你要组装的结果形态 <a class="header-anchor" href="#_1-你要组装的结果形态" aria-label="Permalink to &quot;1. 你要组装的结果形态&quot;">​</a></h2><h3 id="_1-1-最小可合并门禁" tabindex="-1">1.1 最小可合并门禁 <a class="header-anchor" href="#_1-1-最小可合并门禁" aria-label="Permalink to &quot;1.1 最小可合并门禁&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PR</span></span>
<span class="line"><span>  → lint / typecheck</span></span>
<span class="line"><span>  → 单元 + Mock（无真模型 Key）</span></span>
<span class="line"><span>  →（可选）Nest 集成 / Nuxt 冒烟</span></span>
<span class="line"><span>  → 绿则允许合并</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>无评测集也能合并代码；但<strong>不能</strong>把「能合并」当成「能对外」。入口：<a href="/ts-ai/quality/testing-evaluation/agent-unit-testing">Agent 单元测试</a> + <a href="/ts-ai/quality/testing-evaluation/model-tool-mocking">fakeModel() 与 Agent 测试替身</a>。目标是：<strong>确定性、可重复、零账单</strong>。</p><h3 id="_1-2-安全底线已验收的服务" tabindex="-1">1.2 安全底线已验收的服务 <a class="header-anchor" href="#_1-2-安全底线已验收的服务" aria-label="Permalink to &quot;1.2 安全底线已验收的服务&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>鉴权失败 → 401/403（契约稳定）</span></span>
<span class="line"><span>  → 跨租户负例召不回 / 读不到</span></span>
<span class="line"><span>  → 高风险工具无确认不可执行</span></span>
<span class="line"><span>  → Injection 样例无法驱动越权工具</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>产品级规则在本模块；Nest Guard / Middleware 实现分别回 backend / agent。见 <a href="/ts-ai/quality/security-governance/">安全与治理</a>。未通过底线的服务不应进入灰度。</p><h3 id="_1-3-可定位失败的可观测-run" tabindex="-1">1.3 可定位失败的可观测 Run <a class="header-anchor" href="#_1-3-可定位失败的可观测-run" aria-label="Permalink to &quot;1.3 可定位失败的可观测 Run&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一次 Run 失败</span></span>
<span class="line"><span>  → 用 requestId / threadId / runId / tenantId 串日志</span></span>
<span class="line"><span>  → 看到模型 / 工具 / 检索 / 队列哪一段挂</span></span>
<span class="line"><span>  → 成本与延迟可按 Run 或租户归因</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>结构化日志必达；Trace 平台可选。见 <a href="/ts-ai/quality/observability-reliability/structured-logging">结构化日志</a>。「可观测」指能在约定时间内定位，而不是仪表盘好看。</p><h3 id="_1-4-可回滚的一次发布" tabindex="-1">1.4 可回滚的一次发布 <a class="header-anchor" href="#_1-4-可回滚的一次发布" aria-label="Permalink to &quot;1.4 可回滚的一次发布&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Secret 不进镜像 / 前端</span></span>
<span class="line"><span>  → 镜像可复现</span></span>
<span class="line"><span>  → live / ready；SIGTERM 能 drain SSE / 取消在途 Run</span></span>
<span class="line"><span>  → CI 挂测试与（有的话）评测门禁</span></span>
<span class="line"><span>  →（可选）灰度对比质量与成本 → 一键回滚上一镜像</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>主线：<a href="/ts-ai/quality/deployment-operations/configuration-secrets">配置与 Secret</a> → <a href="/ts-ai/quality/deployment-operations/health-checks-graceful-shutdown">健康检查与优雅关闭</a> → <a href="/ts-ai/quality/deployment-operations/ci-cd">CI/CD</a>。回滚路径必须在首次上线前演练一次。</p><h2 id="_2-能力拼装图" tabindex="-1">2. 能力拼装图 <a class="header-anchor" href="#_2-能力拼装图" aria-label="Permalink to &quot;2. 能力拼装图&quot;">​</a></h2><h3 id="_2-1-工程测试与评测必备件" tabindex="-1">2.1 工程测试与评测必备件 <a class="header-anchor" href="#_2-1-工程测试与评测必备件" aria-label="Permalink to &quot;2.1 工程测试与评测必备件&quot;">​</a></h3><table tabindex="0"><thead><tr><th>必备件</th><th>去哪查</th></tr></thead><tbody><tr><td>Agent 纯逻辑 / 工具 / 停止条件</td><td><a href="/ts-ai/quality/testing-evaluation/agent-unit-testing">Agent 单元测试</a></td></tr><tr><td>Fake 模型与工具调用序列</td><td><a href="/ts-ai/quality/testing-evaluation/model-tool-mocking">fakeModel() 与 Agent 测试替身</a></td></tr><tr><td>Nest Provider / 管道 / DB</td><td><a href="/ts-ai/quality/testing-evaluation/nestjs-integration-testing">NestJS 集成测试</a></td></tr><tr><td>Nuxt 流式 / 确认 / 断线</td><td><a href="/ts-ai/quality/testing-evaluation/nuxt-component-e2e-testing">Nuxt 组件与 E2E 测试</a></td></tr><tr><td>失败定义、样例、分层标签</td><td><a href="/ts-ai/quality/testing-evaluation/evaluation-datasets">评测数据集</a></td></tr><tr><td>质量 / 延迟 / 成本 / 安全阈值</td><td><a href="/ts-ai/quality/testing-evaluation/regression-gates">回归门禁</a></td></tr><tr><td>实验台（非门禁前置）</td><td><a href="/ts-ai/quality/testing-evaluation/langsmith-evaluation">评测实验与 LangSmith（可选）</a></td></tr></tbody></table><h3 id="_2-2-安全横切必备件" tabindex="-1">2.2 安全横切必备件 <a class="header-anchor" href="#_2-2-安全横切必备件" aria-label="Permalink to &quot;2.2 安全横切必备件&quot;">​</a></h3><table tabindex="0"><thead><tr><th>必备件</th><th>去哪查</th></tr></thead><tbody><tr><td>身份、资源、操作授权</td><td><a href="/ts-ai/quality/security-governance/authentication-authorization">认证与授权</a></td></tr><tr><td>DB / 缓存 / 向量 / 队列 / 日志隔离</td><td><a href="/ts-ai/quality/security-governance/multi-tenancy-isolation">多租户隔离</a></td></tr><tr><td>工具 ACL、参数约束、HITL</td><td><a href="/ts-ai/quality/security-governance/tool-permissions">工具权限</a></td></tr><tr><td>不可信内容 → 工具边界</td><td><a href="/ts-ai/quality/security-governance/prompt-injection-defense">Prompt Injection 防护</a></td></tr><tr><td>分类、脱敏、审计留痕</td><td><a href="/ts-ai/quality/security-governance/sensitive-data-auditing">敏感数据与审计</a></td></tr><tr><td>依赖锁定 / 镜像来源（按需）</td><td><a href="/ts-ai/quality/security-governance/dependency-supply-chain-security">依赖与供应链安全</a></td></tr></tbody></table><h3 id="_2-3-观测与韧性必备件" tabindex="-1">2.3 观测与韧性必备件 <a class="header-anchor" href="#_2-3-观测与韧性必备件" aria-label="Permalink to &quot;2.3 观测与韧性必备件&quot;">​</a></h3><table tabindex="0"><thead><tr><th>必备件</th><th>去哪查</th></tr></thead><tbody><tr><td>关联 ID 与脱敏</td><td><a href="/ts-ai/quality/observability-reliability/structured-logging">结构化日志</a></td></tr><tr><td>模型 / 工具 / 检索 / 队列指标</td><td><a href="/ts-ai/quality/observability-reliability/traces-metrics">Trace 与指标</a></td></tr><tr><td>OTel 与生产 Trace 关联</td><td><a href="/ts-ai/quality/observability-reliability/opentelemetry-langsmith">OpenTelemetry 接线与 LangSmith 关联</a></td></tr><tr><td>Token / 延迟 / 成本归因</td><td><a href="/ts-ai/quality/observability-reliability/token-latency-cost">Token、延迟与成本</a></td></tr><tr><td>限流、熔断、协议内降级</td><td><a href="/ts-ai/quality/observability-reliability/rate-limits-circuit-breakers-fallbacks">限流、熔断与降级</a></td></tr><tr><td>SLI / 错误预算（进阶）</td><td><a href="/ts-ai/quality/observability-reliability/slo-capacity-planning">SLO 与容量规划</a></td></tr></tbody></table><h3 id="_2-4-与-agent-nest-rag-工作流-前端的接缝" tabindex="-1">2.4 与 Agent / Nest / RAG / 工作流 / 前端的接缝 <a class="header-anchor" href="#_2-4-与-agent-nest-rag-工作流-前端的接缝" aria-label="Permalink to &quot;2.4 与 Agent / Nest / RAG / 工作流 / 前端的接缝&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>前端 Chat（SSE）</span></span>
<span class="line"><span>  → Nest：鉴权、Run、队列、健康检查</span></span>
<span class="line"><span>  → Agent / Middleware / 工具 ACL</span></span>
<span class="line"><span>  →（可选）RAG Retriever（租户过滤）</span></span>
<span class="line"><span>  →（可选）Graph Checkpoint / Interrupt</span></span>
<span class="line"><span>  → 日志 +（可选）OTel Trace</span></span>
<span class="line"><span>  → CI：Mock 测 + 评测门禁 + 扫描</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><table tabindex="0"><thead><tr><th>接缝</th><th>别在本篇重做</th></tr></thead><tbody><tr><td><code>fakeModel()</code> API</td><td><a href="/ts-ai/foundations/langchain-bridge/model-call-tests">模型调用的 Fake、Mock 与错误测试</a>、<a href="/ts-ai/quality/testing-evaluation/model-tool-mocking">fakeModel() 与 Agent 测试替身</a></td></tr><tr><td>Guard / Context 注入</td><td><a href="/ts-ai/backend/ai-service/request-context-tenancy">请求 Context</a></td></tr><tr><td>RAG 召回测方法</td><td><a href="/ts-ai/knowledge/rag-engineering/rag-testing">RAG 测试</a></td></tr><tr><td>图路径 / Trace 可视化</td><td><a href="/ts-ai/workflow/workflow-quality/">工作流质量</a></td></tr><tr><td>SSE 取消 / 重连 UX</td><td><a href="/ts-ai/integration/interaction-protocols/cancellation-reconnection-deduplication">取消、重连与去重</a></td></tr></tbody></table><p>本模块负责：<strong>怎么把上述信号挂进门禁与上线标准</strong>。</p><h2 id="_3-推荐配方" tabindex="-1">3. 推荐配方 <a class="header-anchor" href="#_3-推荐配方" aria-label="Permalink to &quot;3. 推荐配方&quot;">​</a></h2><h3 id="_3-1-配方-a-mock-单元-ci-红线" tabindex="-1">3.1 配方 A：Mock + 单元 + CI 红线 <a class="header-anchor" href="#_3-1-配方-a-mock-单元-ci-红线" aria-label="Permalink to &quot;3.1 配方 A：Mock + 单元 + CI 红线&quot;">​</a></h3><p><strong>何时用：</strong> 任何可合并 PR 的底线；无真模型 Key 也能绿。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>vitest / jest</span></span>
<span class="line"><span>  → Fake 模型固定回复 + 工具 Mock 序列</span></span>
<span class="line"><span>  → Agent 纯逻辑 / Middleware 单测</span></span>
<span class="line"><span>  → CI：失败即阻断合并</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>拼：<a href="/ts-ai/quality/testing-evaluation/model-tool-mocking">fakeModel() 与 Agent 测试替身</a> + <a href="/ts-ai/quality/testing-evaluation/agent-unit-testing">Agent 单元测试</a>。有 Nest / Nuxt 时再叠 <a href="/ts-ai/quality/testing-evaluation/nestjs-integration-testing">NestJS 集成测试</a>、<a href="/ts-ai/quality/testing-evaluation/nuxt-component-e2e-testing">Nuxt 组件与 E2E</a>。<strong>禁止</strong>在 CI 默认真打付费 API。</p><p><strong>验收信号：</strong> PR 流水线红线稳定；本地无 <code>.env</code> 模型 Key 也能跑通主测包。</p><h3 id="_3-2-配方-b-评测集-回归门禁进-ci" tabindex="-1">3.2 配方 B：评测集 + 回归门禁进 CI <a class="header-anchor" href="#_3-2-配方-b-评测集-回归门禁进-ci" aria-label="Permalink to &quot;3.2 配方 B：评测集 + 回归门禁进 CI&quot;">​</a></h3><p><strong>何时用：</strong> Prompt / 检索 / 工具策略会改质量；要防静默退化。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>版本化评测集（标签：正确 / 幻觉 / 越权 / 空检索）</span></span>
<span class="line"><span>  → 离线或定时跑 Evaluator</span></span>
<span class="line"><span>  → 阈值：通过率 / P95 延迟 / 单次成本 / 安全负例</span></span>
<span class="line"><span>  → CI 或 release job：超阈阻断</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>拼：<a href="/ts-ai/quality/testing-evaluation/evaluation-datasets">评测数据集</a> + <a href="/ts-ai/quality/testing-evaluation/regression-gates">回归门禁</a>。RAG / Graph 专项套件并入同一门禁，方法细节仍归 knowledge / workflow。</p><p><strong>验收信号：</strong> 故意改坏 Prompt 或过滤条件后，门禁变红；修回后变绿。阈值变更有记录。</p><h3 id="_3-3-配方-c-认证租户工具权限-injection-用例" tabindex="-1">3.3 配方 C：认证租户工具权限 + Injection 用例 <a class="header-anchor" href="#_3-3-配方-c-认证租户工具权限-injection-用例" aria-label="Permalink to &quot;3.3 配方 C：认证租户工具权限 + Injection 用例&quot;">​</a></h3><p><strong>何时用：</strong> 多租户、有写操作工具、或接受外部文档 / URL。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>认证授权用例（未登录 / 无权限）</span></span>
<span class="line"><span>  + 跨租户负例（DB / 向量 / 缓存 / 日志）</span></span>
<span class="line"><span>  + 高风险工具无确认 → 拒绝</span></span>
<span class="line"><span>  + Injection 语料 → 不得触发越权工具</span></span>
<span class="line"><span>  +（可选）敏感字段脱敏与审计事件</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>拼：<a href="/ts-ai/quality/security-governance/authentication-authorization">认证与授权</a> + <a href="/ts-ai/quality/security-governance/multi-tenancy-isolation">多租户隔离</a> + <a href="/ts-ai/quality/security-governance/tool-permissions">工具权限</a> + <a href="/ts-ai/quality/security-governance/prompt-injection-defense">Prompt Injection 防护</a>。审计与脱敏见 <a href="/ts-ai/quality/security-governance/sensitive-data-auditing">敏感数据与审计</a>。</p><p><strong>验收信号：</strong> 跨租户负例全红（召不回 / 读不到）；Injection 样例零越权工具调用。</p><h3 id="_3-4-配方-d-日志关联-id-成本归因-限流降级" tabindex="-1">3.4 配方 D：日志关联 ID + 成本归因 + 限流降级 <a class="header-anchor" href="#_3-4-配方-d-日志关联-id-成本归因-限流降级" aria-label="Permalink to &quot;3.4 配方 D：日志关联 ID + 成本归因 + 限流降级&quot;">​</a></h3><p><strong>何时用：</strong> 准备对外或灰度；要能定位失败 Run 且过载不裂契约。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>每条日志带 requestId / threadId / runId / tenantId</span></span>
<span class="line"><span>  → 模型与工具失败可检索</span></span>
<span class="line"><span>  → Token / 延迟按功能或租户汇总</span></span>
<span class="line"><span>  → 超限 → 限流 / 熔断 / 降级（仍发协议内错误或降级事件）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>拼：<a href="/ts-ai/quality/observability-reliability/structured-logging">结构化日志</a> + <a href="/ts-ai/quality/observability-reliability/token-latency-cost">Token、延迟与成本</a> + <a href="/ts-ai/quality/observability-reliability/rate-limits-circuit-breakers-fallbacks">限流、熔断与降级</a>。需要分布式 Trace 时再读 <a href="/ts-ai/quality/observability-reliability/traces-metrics">Trace 与指标</a> 与 <a href="/ts-ai/quality/observability-reliability/opentelemetry-langsmith">OTel 接线</a>。</p><p><strong>验收信号：</strong> 给定一个失败 <code>runId</code>，五分钟内定位到失败层；压测超限时前端收到可解释终态而非悬挂流。</p><h3 id="_3-5-配方-e-secret-健康检查-ci-cd-挂门禁-可选灰度" tabindex="-1">3.5 配方 E：Secret + 健康检查 + CI/CD 挂门禁（可选灰度） <a class="header-anchor" href="#_3-5-配方-e-secret-健康检查-ci-cd-挂门禁-可选灰度" aria-label="Permalink to &quot;3.5 配方 E：Secret + 健康检查 + CI/CD 挂门禁（可选灰度）&quot;">​</a></h3><p><strong>何时用：</strong> 第一次生产发布；或已有 A–D，要把门禁钉进流水线。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>环境校验 + Secret 注入（非镜像 bake-in）</span></span>
<span class="line"><span>  → Docker 可复现构建</span></span>
<span class="line"><span>  → /live /ready；优雅关闭 drain Run</span></span>
<span class="line"><span>  → CI：配方 A（必）+ B/C 扫描（有则挂）</span></span>
<span class="line"><span>  →（可选）按流量或租户灰度，对比门禁同款指标 → 回滚</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>拼：<a href="/ts-ai/quality/deployment-operations/configuration-secrets">配置与 Secret</a> + <a href="/ts-ai/quality/deployment-operations/docker">Docker</a> + <a href="/ts-ai/quality/deployment-operations/health-checks-graceful-shutdown">健康检查与优雅关闭</a> + <a href="/ts-ai/quality/deployment-operations/ci-cd">CI/CD</a>。灰度进阶：<a href="/ts-ai/quality/deployment-operations/canary-releases">灰度发布</a>。</p><p><strong>验收信号：</strong> 缺 Secret 时进程拒绝启动；滚动发布不丢在途 Run 语义；回滚只需切上一镜像标签。</p><h2 id="_4-决策表" tabindex="-1">4. 决策表 <a class="header-anchor" href="#_4-决策表" aria-label="Permalink to &quot;4. 决策表&quot;">​</a></h2><h3 id="_4-1-何时上-langsmith-评测实验" tabindex="-1">4.1 何时上 LangSmith 评测实验 <a class="header-anchor" href="#_4-1-何时上-langsmith-评测实验" aria-label="Permalink to &quot;4.1 何时上 LangSmith 评测实验&quot;">​</a></h3><table tabindex="0"><thead><tr><th>条件</th><th>选</th></tr></thead><tbody><tr><td>还没有版本化评测集与本地/CI 阈值</td><td><strong>先配方 B</strong>；不上平台</td></tr><tr><td>要多人对比 Prompt / 数据集版本、看 Run 轨迹</td><td><strong>LangSmith 实验台</strong>（<a href="/ts-ai/quality/testing-evaluation/langsmith-evaluation">评测实验</a>）</td></tr><tr><td>只要生产链路关联 request ↔ Agent Trace</td><td><strong>观测组 OTel / LangSmith 关联</strong>，不是评测篇</td></tr><tr><td>把平台当唯一门禁、本地跑不起来</td><td><strong>不推荐</strong></td></tr></tbody></table><p>默认：<strong>门禁先于平台</strong>（与 <a href="/ts-ai/quality/">质量总览</a> 一致）。</p><h3 id="_4-2-门禁阈值-阻断-vs-仅告警" tabindex="-1">4.2 门禁阈值：阻断 vs 仅告警 <a class="header-anchor" href="#_4-2-门禁阈值-阻断-vs-仅告警" aria-label="Permalink to &quot;4.2 门禁阈值：阻断 vs 仅告警&quot;">​</a></h3><table tabindex="0"><thead><tr><th>条件</th><th>选</th></tr></thead><tbody><tr><td>安全负例失败、跨租户串数据、高风险工具无确认</td><td><strong>阻断</strong>发布 / 合并</td></tr><tr><td>主路径正确率跌破约定基线、空检索却胡答率上升</td><td><strong>阻断</strong>（配方 B）</td></tr><tr><td>P95 延迟 / 单次成本轻微超预算、样例噪声大</td><td><strong>告警</strong> + 限时修；连续恶化再升阻断</td></tr><tr><td>新指标尚无基线</td><td>先告警收集 1–2 周，再写入 <a href="/ts-ai/quality/testing-evaluation/regression-gates">回归门禁</a></td></tr></tbody></table><h3 id="_4-3-灰度按流量-vs-按租户" tabindex="-1">4.3 灰度按流量 vs 按租户 <a class="header-anchor" href="#_4-3-灰度按流量-vs-按租户" aria-label="Permalink to &quot;4.3 灰度按流量 vs 按租户&quot;">​</a></h3><table tabindex="0"><thead><tr><th>条件</th><th>选</th></tr></thead><tbody><tr><td>无强租户边界、要快速看整体质量 / 成本曲线</td><td><strong>按流量百分比</strong></td></tr><tr><td>SaaS 多租户、合同/数据隔离敏感、要可撤回名单</td><td><strong>按租户（或租户白名单）</strong></td></tr><tr><td>两者都要</td><td>先租户金丝雀，再扩流量；指标与门禁同口径</td></tr><tr><td>图版本 / Prompt 灰度</td><td>部署篇灰度 + 工作流发布兼容；勿只改前端</td></tr></tbody></table><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>还不能 Mock 绿？ → 配方 A</span></span>
<span class="line"><span>怕 Prompt 退化？ → 配方 B</span></span>
<span class="line"><span>有租户 / 写工具 / 外链？ → 配方 C</span></span>
<span class="line"><span>要定位失败 Run？ → 配方 D</span></span>
<span class="line"><span>要第一次上线？ → 配方 E（叠 A–D）</span></span>
<span class="line"><span>纠结 LangSmith？ → §4.1</span></span>
<span class="line"><span>纠结卡不卡发布？ → §4.2</span></span>
<span class="line"><span>纠结怎么灰度？ → §4.3</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h2 id="_5-能力自检清单" tabindex="-1">5. 能力自检清单 <a class="header-anchor" href="#_5-能力自检清单" aria-label="Permalink to &quot;5. 能力自检清单&quot;">​</a></h2><p>进入 <a href="/ts-ai/architecture/">架构与实战</a> 或对外发布前勾选。勾不完回 §6。</p><h3 id="_5-1-测试与评测自检" tabindex="-1">5.1 测试与评测自检 <a class="header-anchor" href="#_5-1-测试与评测自检" aria-label="Permalink to &quot;5.1 测试与评测自检&quot;">​</a></h3><ul><li>[ ] CI 无真模型 Key；Fake / Mock 覆盖主路径与至少一条失败注入</li><li>[ ] Agent 停止条件、工具错误路径有单测</li><li>[ ] Nest 关键 API（创建 Run / 取消）有集成测或契约测</li><li>[ ] 评测集版本化；含幻觉 / 越权 / 空检索等失败标签</li><li>[ ] 回归阈值写入 CI 或 release job；知道哪些阻断、哪些告警</li><li>[ ] RAG / Graph 专项套件（若启用）已并入同一门禁口径</li></ul><h3 id="_5-2-安全自检" tabindex="-1">5.2 安全自检 <a class="header-anchor" href="#_5-2-安全自检" aria-label="Permalink to &quot;5.2 安全自检&quot;">​</a></h3><ul><li>[ ] 未登录 / 无权限响应符合鉴权协议，不泄露他户数据</li><li>[ ] 跨租户负例覆盖 DB、缓存、向量、队列、日志至少一层</li><li>[ ] 高风险工具默认拒绝或强制 HITL，且有审计事件</li><li>[ ] Injection 用例无法驱动越权工具或改写系统策略</li><li>[ ] Secret / 证件号等敏感字段日志已脱敏</li><li>[ ] 依赖锁定；生产镜像来源可追溯（按需）</li></ul><h3 id="_5-3-观测与可靠性自检" tabindex="-1">5.3 观测与可靠性自检 <a class="header-anchor" href="#_5-3-观测与可靠性自检" aria-label="Permalink to &quot;5.3 观测与可靠性自检&quot;">​</a></h3><ul><li>[ ] 任意失败 Run 能用关联 ID 在日志中一次搜齐</li><li>[ ] 能区分模型超时、工具 5xx、检索空、队列堆积</li><li>[ ] Token / 延迟 / 成本可按功能或租户汇总，有预算意识</li><li>[ ] 限流 / 熔断后前端仍收到协议内错误或降级事件（不静默断流）</li><li>[ ] （可选）OTel Trace 与 Agent 轨迹可对齐到同一 <code>runId</code></li></ul><h3 id="_5-4-部署自检" tabindex="-1">5.4 部署自检 <a class="header-anchor" href="#_5-4-部署自检" aria-label="Permalink to &quot;5.4 部署自检&quot;">​</a></h3><ul><li>[ ] 模型 Key 与 DB 密码不在镜像层 / 前端包</li><li>[ ] <code>/live</code> 与 <code>/ready</code> 语义分离；依赖未就绪时不接流量</li><li>[ ] SIGTERM 停止新 SSE，并取消或转移在途 Run</li><li>[ ] CI/CD 挂上配方 A，并在有评测集时挂配方 B</li><li>[ ] 发布可回滚到上一镜像；灰度（若启用）有对比指标与退出条件</li><li>[ ] （进阶）Checkpoint / 向量索引备份与 RTO/RPO 有文档</li></ul><h2 id="_6-未通过时的回跳路径" tabindex="-1">6. 未通过时的回跳路径 <a class="header-anchor" href="#_6-未通过时的回跳路径" aria-label="Permalink to &quot;6. 未通过时的回跳路径&quot;">​</a></h2><table tabindex="0"><thead><tr><th>缺口</th><th>回跳</th></tr></thead><tbody><tr><td>Mock / 单测不会写</td><td><a href="/ts-ai/quality/testing-evaluation/">测试与评测</a> → 配方 A 链接文</td></tr><tr><td>评测集空洞、阈值拍脑袋</td><td><a href="/ts-ai/quality/testing-evaluation/evaluation-datasets">评测数据集</a> → <a href="/ts-ai/quality/testing-evaluation/regression-gates">回归门禁</a></td></tr><tr><td>LangSmith 与门禁分不清</td><td>§4.1 + <a href="/ts-ai/quality/testing-evaluation/langsmith-evaluation">评测实验</a> vs <a href="/ts-ai/quality/observability-reliability/opentelemetry-langsmith">OTel 关联</a></td></tr><tr><td>鉴权 / 租户 / 工具 / Injection</td><td><a href="/ts-ai/quality/security-governance/">安全与治理</a></td></tr><tr><td>失败 Run 找不到</td><td><a href="/ts-ai/quality/observability-reliability/structured-logging">结构化日志</a></td></tr><tr><td>成本飙、过载裂契约</td><td><a href="/ts-ai/quality/observability-reliability/token-latency-cost">Token、延迟与成本</a> → <a href="/ts-ai/quality/observability-reliability/rate-limits-circuit-breakers-fallbacks">限流、熔断与降级</a></td></tr><tr><td>Secret / 健康检查 / 流水线</td><td><a href="/ts-ai/quality/deployment-operations/">部署与运维</a></td></tr><tr><td>灰度策略犹豫</td><td>§4.3 + <a href="/ts-ai/quality/deployment-operations/canary-releases">灰度发布</a></td></tr><tr><td>Nest Run / SSE 本身不稳</td><td><a href="/ts-ai/backend/assembly/assembly-recipes-checklist">服务端组装配方</a></td></tr><tr><td>前端协议 / HITL 缺口</td><td><a href="/ts-ai/integration/assembly/assembly-recipes-checklist">全栈集成组装配方</a></td></tr><tr><td>检索串租户 / 无引用</td><td><a href="/ts-ai/knowledge/assembly/assembly-recipes-checklist">RAG 组装配方</a></td></tr></tbody></table><h2 id="_7-验收标准" tabindex="-1">7. 验收标准 <a class="header-anchor" href="#_7-验收标准" aria-label="Permalink to &quot;7. 验收标准&quot;">​</a></h2><p>能不看目录，根据场景在配方 A–E 中选型；能区分 LangSmith 实验台 vs 生产 Trace、阻断 vs 告警、流量灰度 vs 租户灰度；能用 §5 指出测试 / 安全 / 观测 / 部署中未完成项。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PR 红线           → 配方 A</span></span>
<span class="line"><span>防质量退化       → 配方 B</span></span>
<span class="line"><span>多租户 / 写工具  → 配方 C</span></span>
<span class="line"><span>可定位 + 可降级  → 配方 D</span></span>
<span class="line"><span>第一次上线       → 配方 E（叠 A–D，灰度可选）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div>`,78)])])}const b=t(i,[["render",r]]);export{u as __pageData,b as default};
